266	    public Sheet load(String id, String user) {
267	        return sheets.findById(id).orElseGet(() -> create(id, user));
268	    }
269	
270	    /** The sheet's "today": the date every decision and default date in the sheet uses. */
271	    @Transactional(readOnly = true)
272	    public LocalDate today(String id) {
273	        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
274	    }
275	
276	    @Transactional
277	    public Sheet setToday(String id, String user, LocalDate today) {
278	        Sheet sheet = load(id, user);
279	        sheet.setToday(today);
280	        return sheet;
281	    }
282	
283	    /**
284	     * Change the sheet's clerk limit (two decimals; null for no limit), floor (two decimals; null
285	     * leaves it as it is) terms (days; null leaves them as they are) and late percent (two
286	     * decimals; null leaves it as it is). Each change is recorded as
287	     * SETTING_CHANGED key=&lt;key&gt; value=&lt;value&gt;, clerk-limit first, then floor, then terms, then late-pct, the
288	     * clerk limit's value empty for no limit; setting a value it already has records nothing.
289	     */
290	    @Transactional
291	    public Sheet setSettings(String id, String user, BigDecimal limit, BigDecimal floor, Integer terms,
292	            BigDecimal latePct) {
293	        load(id, user);
294	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
295	        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY);
296	        if (!Objects.equals(sheet.getClerkLimit(), scaled)) {
297	            sheet.setClerkLimit(scaled);
298	            audit.change("SETTING_CHANGED", id, user, "key=clerk-limit",
299	                    "value=" + (scaled == null ? "" : scaled.toPlainString()));
300	        }
301	        if (floor != null) {
302	            BigDecimal scaledFloor = floor.setScale(2, RoundingMode.UNNECESSARY);
303	            if (scaledFloor.compareTo(sheet.getFloor()) != 0) {
304	                sheet.setFloor(scaledFloor);
305	                audit.change("SETTING_CHANGED", id, user, "key=floor", "value=" + scaledFloor.toPlainString());
306	            }
307	        }
308	        if (terms != null && terms != sheet.getTerms()) {
309	            sheet.setTerms(terms);
310	            audit.change("SETTING_CHANGED", id, user, "key=terms", "value=" + terms);
311	        }
312	        if (latePct != null) {
313	            BigDecimal scaledPct = latePct.setScale(2, RoundingMode.UNNECESSARY);
314	            if (scaledPct.compareTo(sheet.getLatePct()) != 0) {
315	                sheet.setLatePct(scaledPct);
316	                audit.change("SETTING_CHANGED", id, user, "key=late-pct", "value=" + scaledPct.toPlainString());
317	            }
318	        }
319	        return sheet;
320	    }
321	
322	    /**
323	     * The sheet, locked until the caller's transaction ends, so changes that must happen one at a
324	     * time on a sheet (such as giving out claim numbers) do; empty if the sheet was never loaded.
325	     */
326	    @Transactional
327	    public Optional<Sheet> lock(String id) {
328	        return sheets.findLockedById(id);
329	    }
330	
331	    private Sheet create(String id, String user) {
332	        try {
333	            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock)));
334	        } catch (DataIntegrityViolationException e) {
335	            // Another user loaded the same new sheet at the same moment.
336	            return sheets.findById(id).orElseThrow(() -> e);
337	        }
338	    }
339	}
340	package net.officefloor.hq.app.claim;
341	
342	import java.math.BigDecimal;
343	import java.math.RoundingMode;
344	import java.time.LocalDate;
345	import java.util.ArrayList;
346	import java.util.List;
347	import net.officefloor.hq.app.Audit;
348	import net.officefloor.hq.app.person.Person;
349	import net.officefloor.hq.app.period.PeriodRepository;
350	import net.officefloor.hq.app.person.PersonRepository;
351	import net.officefloor.hq.app.rate.RateService;
352	import net.officefloor.hq.app.role.Role;
353	import net.officefloor.hq.app.role.RoleService;
354	import net.officefloor.hq.app.sheet.Sheet;
355	import net.officefloor.hq.app.sheet.SheetService;
356	import org.springframework.http.HttpStatus;
357	import org.springframework.stereotype.Service;
358	import org.springframework.transaction.annotation.Transactional;
359	import org.springframework.web.server.ResponseStatusException;
360	
361	/**
362	 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
363	 * missing note is stored empty. Only a DRAFT claim can be edited (409); an open claim is changed by
364	 * voiding it and adding a new one. No claim dated in a closed period can be added, edited or change
365	 * status (423). No claim dated after its person's retirement date can be added or edited (422).
366	 * A claim with a negative amount is a correction: it must name, by number, a SETTLED claim of the
367	 * same person, or it is refused (422); a claim that is not a correction names none.
368	 */
369	@Service
370	public class ClaimService {
371	
372	    private final ClaimRepository claims;
373	    private final PersonRepository people;
374	    private final PeriodRepository periods;
375	    private final RateService rates;
376	    private final RoleService roles;
377	    private final SheetService sheets;
378	    private final Audit audit;
379	
380	    public ClaimService(ClaimRepository claims, PersonRepository people, PeriodRepository periods, RateService rates,
381	            RoleService roles, SheetService sheets, Audit audit) {
382	        this.roles = roles;
383	        this.claims = claims;
384	        this.people = people;
385	        this.periods = periods;
386	        this.rates = rates;
387	        this.sheets = sheets;
388	        this.audit = audit;
389	    }
390	
391	    @Transactional(readOnly = true)
392	    public List<Claim> list(String sheetId) {
393	        return claims.findBySheetIdOrderByIdDesc(sheetId);
394	    }
395	
396	    @Transactional
397	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
398	            Long corrects) {
399	        sheets.load(sheetId, user);
400	        // Lock the sheet, so a period closed at the same moment is seen.
401	        sheets.lock(sheetId);
402	        Person person = people.findByIdAndSheetId(personId, sheetId)
403	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
404	        LocalDate on = date != null ? date : sheets.today(sheetId);
405	        refuseIfClosed(sheetId, on);
406	        refuseIfRetired(person, on);
407	        Long corrected = correctedNumber(sheetId, personId, amount, corrects);
408	        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount), on, note != null ? note : "", corrected));
409	        record("CLAIM_ADDED", user, person, claim);
410	        return claim;
411	    }
412	
413	    @Transactional
414	    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note,
415	            Long corrects) {
416	        sheets.lock(sheetId);
417	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
418	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
419	        LocalDate on = date != null ? date : sheets.today(sheetId);
420	        if (claim.getStatus() != ClaimStatus.DRAFT) {
421	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be edited");
422	        }
423	        refuseIfClosed(sheetId, claim.getDate());
424	        refuseIfClosed(sheetId, on);
425	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
426	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
427	        refuseIfRetired(person, on);
428	        Long corrected = correctedNumber(sheetId, person.getId(), amount, corrects);
429	        claim.setAmount(scaled(amount));
430	        claim.setCorrects(corrected);
431	        claim.setDate(on);
432	        claim.setNote(note != null ? note : "");
433	        record("CLAIM_EDITED", user, person, claim);
434	        return claim;
435	    }
436	
437	    /**
438	     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
439	     * gives the claim the sheet's next number; a voided claim keeps it (the number is never given again).
440	     * Opening records who opened it; that user cannot settle it (403).
441	     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to
442	     * the sheet's floor, with its late charge added if it is overdue; later floor and late percent changes
443	     * leave it as fixed. A correction's due is its amount times that rate, rounded the same way, with no
444	     * floor and no late charge. A clerk
445	     * can settle a claim only when that due is at or below the sheet's clerk limit, if it has one (403);
446	     * a claim with no due (no rate) is then refused too, as it cannot be shown to be within the limit.
447	     * A steward settles any claim.
448	     */
449	    @Transactional
450	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
451	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
452	        // and a period closed at the same moment is seen.
453	        Sheet sheet = sheets.lock(sheetId)
454	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
455	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
456	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
457	        refuseIfClosed(sheetId, claim.getDate());
458	        if (!claim.getStatus().canBecome(next)) {
459	            throw new ResponseStatusException(HttpStatus.CONFLICT,
460	                    "A " + claim.getStatus() + " claim cannot become " + next);
461	        }
462	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
463	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
464	        }
465	        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
466	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
467	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
468	        claim.setStatus(next);
469	        claim.setNumber(number);
470	        if (next == ClaimStatus.OPEN) {
471	            claim.setOpenedBy(user);
472	        }
473	        List<String> extra = new ArrayList<>();
474	        if (next == ClaimStatus.SETTLED) {
475	            BigDecimal due = sheet.liveDue(rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
476	                    .map(rate -> claim.getAmount().multiply(rate.getRate())
477	                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
478	                    .orElse(null), claim.getDate(), claim.isCorrection());
479	            refuseIfOverClerkLimit(sheet, user, due);
480	            claim.setSettledDue(due);
481	            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
482	        }
483	        record(switch (next) {
484	            case OPEN -> "CLAIM_OPENED";
485	            case SETTLED -> "CLAIM_SETTLED";
486	            case VOID -> "CLAIM_VOIDED";
487	            case DRAFT -> throw new IllegalStateException();
488	        }, user, person, claim, number, extra);
489	        return claim;
490	    }
491	
492	    /**
493	     * The number a claim corrects: for a negative amount, the number of a SETTLED claim of the same
494	     * person, refused (422) when none is named or it names no such claim; none for any other amount.
495	     */
496	    private Long correctedNumber(String sheetId, Long personId, BigDecimal amount, Long corrects) {
497	        if (amount.signum() >= 0) {
498	            return null;
499	        }
500	        boolean settled = corrects != null && claims.findFirstBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
501	                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED)
502	                .isPresent();
503	        if (!settled) {
504	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
505	                    "A negative amount must correct a settled claim of the same person");
506	        }
507	        return corrects;
508	    }
509	
510	    /** Refuse (403) a clerk settling a claim whose due is above the sheet's clerk limit. */
511	    private void refuseIfOverClerkLimit(Sheet sheet, String user, BigDecimal due) {
512	        BigDecimal limit = sheet.getClerkLimit();
513	        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
514	            return;
515	        }
516	        if (due == null || due.compareTo(limit) > 0) {
517	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
518	                    "A clerk cannot settle a claim with a due above " + limit.toPlainString());
519	        }
520	    }
521	
522	    /** Refuse (423) a change to a claim dated in a closed period. */
523	    private void refuseIfClosed(String sheetId, LocalDate date) {
524	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
525	                .filter(period -> period.isClosed() && period.contains(date))
526	                .findFirst()
527	                .ifPresent(period -> {
528	                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
529	                });
530	    }
531	
532	    /** Refuse (422) a claim dated after its person's retirement date. */
533	    private static void refuseIfRetired(Person person, LocalDate date) {
534	        if (person.retiredOn(date)) {
535	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
536	                    person.getName() + " is retired from " + person.getRetiredFrom());
537	        }
538	    }
539	
540	    private void record(String event, String user, Person person, Claim claim) {
541	        record(event, user, person, claim, claim.getNumber(), List.of());
542	    }
543	
544	    /**
545	     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
546	     */
547	    private void record(String event, String user, Person person, Claim claim, Long number, List<String> extra) {
548	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
549	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
550	        if (number != null) {
551	            fields.add("number=" + number);
552	        }
553	        fields.addAll(extra);
554	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
555	    }
556	
557	    private static BigDecimal scaled(BigDecimal amount) {
558	        return amount.setScale(2, RoundingMode.UNNECESSARY);
559	    }
560	}
561	-- The sheet's floor: every live due (not a settled claim's fixed due) is at least it.
562	ALTER TABLE sheet ADD COLUMN floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;
563	-- The sheet's terms: the number of days after a claim's date that it is due by.
564	ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
565	-- The sheet's late percent: an overdue claim's live due gains it, of its floored due, for every full 30 days overdue.
566	ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;
567	import { Component, computed, effect, inject, linkedSignal, signal, untracked } from '@angular/core';
568	import { AMOUNT } from '../../core/claims';
569	import { RATE } from '../../core/rates';
570	import { ROLES, RoleName, Roles } from '../../core/roles';
571	import { Session } from '../../core/session';
572	
573	// The sheet's settings (the clerk limit, the floor, the terms and the late percent) and the roles given to user names.
574	@Component({
575	  selector: 'app-settings',
576	  template: `
577	    <section aria-labelledby="settings-heading">
578	      <h2 id="settings-heading">Settings</h2>
579	
580	      <p>Clerk limit <strong data-testid="setting-clerk-limit-current">{{ session.clerkLimit() ?? '' }}</strong></p>
581	      <form (submit)="saveSettings($event)">
582	        <label for="setting-clerk-limit">Clerk limit (blank for no limit)</label>
