584	          id="setting-clerk-limit"
585	          inputmode="decimal"
586	          data-testid="setting-clerk-limit"
587	          [value]="clerkLimit()"
588	          (input)="clerkLimit.set($any($event.target).value); settingsError.set(null)"
589	        />
590	        <p>Floor <strong data-testid="setting-floor-current">{{ session.floor() ?? '' }}</strong></p>
591	        <label for="setting-floor">Floor (the least any live due can be)</label>
592	        <input
593	          id="setting-floor"
594	          inputmode="decimal"
595	          data-testid="setting-floor"
596	          [value]="floor()"
597	          (input)="floor.set($any($event.target).value); settingsError.set(null)"
598	        />
599	        <p>Terms (days) <strong data-testid="setting-terms-current">{{ session.terms() ?? '' }}</strong></p>
600	        <label for="setting-terms">Terms (days after a claim's date it is due by)</label>
601	        <input
602	          id="setting-terms"
603	          inputmode="numeric"
604	          data-testid="setting-terms"
605	          [value]="terms()"
606	          (input)="terms.set($any($event.target).value); settingsError.set(null)"
607	        />
608	        <p>Late percent <strong data-testid="setting-late-pct-current">{{ session.latePct() ?? '' }}</strong></p>
609	        <label for="setting-late-pct">Late percent (added per full 30 days a claim is overdue)</label>
610	        <input
611	          id="setting-late-pct"
612	          inputmode="decimal"
613	          data-testid="setting-late-pct"
614	          [value]="latePct()"
615	          (input)="latePct.set($any($event.target).value); settingsError.set(null)"
616	        />
617	        <button type="submit" data-testid="settings-save">Save settings</button>
618	        @if (settingsError(); as err) {
619	          <p role="alert" data-testid="settings-error">{{ err }}</p>
620	        }
621	      </form>
622	
623	      <h3>Roles</h3>
624	      <form (submit)="saveRole($event)">
625	        <label for="role-user">User name</label>
626	        <input
627	          id="role-user"
628	          data-testid="role-form-user"
629	          [value]="user()"
630	          (input)="user.set($any($event.target).value); roleError.set(null)"
631	        />
632	        <label for="role-role">Role (clerk or steward)</label>
