639	        <button type="submit" data-testid="role-form-submit">Set role</button>
640	        @if (roleError(); as err) {
641	          <p role="alert" data-testid="role-form-error">{{ err }}</p>
642	        }
643	      </form>
644	
645	      <table>
646	        <caption>Roles (any other name is a clerk; the name being entered is shown with its role)</caption>
647	        <thead>
648	          <tr><th scope="col">User</th><th scope="col">Role</th></tr>
649	        </thead>
650	        <tbody>
651	          @for (r of roles.all(); track r.user) {
652	            <tr [attr.data-testid]="'role-row-' + r.user">
653	              <td data-testid="role-user">{{ r.user }}</td>
654	              <td data-testid="role-value">{{ r.role }}</td>
655	            </tr>
656	          }
657	          @if (typedDefault(); as name) {
658	            <tr [attr.data-testid]="'role-row-' + name">
659	              <td data-testid="role-user">{{ name }}</td>
660	              <td data-testid="role-value">clerk</td>
661	            </tr>
662	          }
663	        </tbody>
664	      </table>
665	    </section>
666	  `,
667	})
668	export class SettingsPanel {
669	  protected readonly session = inject(Session);
670	  protected readonly roles = inject(Roles);
671	
672	  protected readonly clerkLimit = linkedSignal(() => this.session.clerkLimit() ?? '');
673	  protected readonly floor = linkedSignal(() => this.session.floor() ?? '');
674	  protected readonly terms = linkedSignal(() => String(this.session.terms() ?? ''));
675	  protected readonly latePct = linkedSignal(() => this.session.latePct() ?? '');
676	  protected readonly settingsError = signal<string | null>(null);
677	  protected readonly user = signal('');
678	  protected readonly role = signal('');
679	  protected readonly roleError = signal<string | null>(null);
680	  /** The name being entered in the role form when it has no role given, so it shows as a clerk. */
681	  protected readonly typedDefault = computed(() => {
682	    const name = this.user().trim();
683	    return name && !this.roles.all().some((r) => r.user === name) ? name : null;
684	  });
685	  /** Set while a submit awaits the store, so a second submit does not store it twice. */
686	  private savingSettings = false;
687	  private savingRole = false;
688	
689	  constructor() {
690	    // Re-read the store each time the sheet is (re-)loaded.
691	    effect(() => {
692	      this.session.loads();
693	      untracked(() => {
694	        this.settingsError.set(null);
695	        this.roleError.set(null);
696	        void this.session.track(this.roles.reload());
697	      });
698	    });
699	  }
700	
701	  protected async saveSettings(event: Event): Promise<void> {
702	    event.preventDefault();
703	    if (this.savingSettings) return;
704	    this.settingsError.set(null);
705	    const limit = this.clerkLimit().trim();
706	    if (limit && !AMOUNT.test(limit)) {
707	      this.settingsError.set('Enter a clerk limit of 0.00 or more, with at most two decimals, or leave it blank.');
708	      return;
709	    }
710	    const floor = this.floor().trim();
711	    if (!AMOUNT.test(floor)) {
712	      this.settingsError.set('Enter a floor of 0.00 or more, with at most two decimals.');
713	      return;
714	    }
715	    const terms = this.terms().trim();
716	    if (!/^\d{1,4}$/.test(terms)) {
717	      this.settingsError.set('Enter terms as a whole number of days, from 0 to 9999.');
718	      return;
719	    }
720	    const latePct = this.latePct().trim();
721	    if (!RATE.test(latePct)) {
722	      this.settingsError.set('Enter a late percent of 0.00 or more, below 1000, with at most two decimals.');
723	      return;
724	    }
725	    this.savingSettings = true;
726	    try {
727	      await this.session.setSettings(limit || null, floor, terms, latePct);
728	    } catch {
729	      this.settingsError.set('The settings could not be saved.');
730	    } finally {
731	      this.savingSettings = false;
732	    }
733	  }
734	
735	  protected async saveRole(event: Event): Promise<void> {
736	    event.preventDefault();
737	    if (this.savingRole) return;
738	    this.roleError.set(null);
739	    const user = this.user().trim();
740	    const role = this.role().trim();
741	    if (!user) {
742	      this.roleError.set('Enter a user name.');
743	      return;
744	    }
745	    if (!ROLES.includes(role as RoleName)) {
746	      this.roleError.set('Enter a role: clerk or steward.');
747	      return;
748	    }
749	    this.savingRole = true;
750	    try {
751	      await this.roles.set(user, role as RoleName);
752	      this.user.set('');
753	      this.role.set('');
754	    } catch {
755	      this.roleError.set('The role could not be set.');
756	    } finally {
757	      this.savingRole = false;
758	    }
759	  }
760	}
