            <tr [attr.data-testid]="'role-row-' + r.user">
              <td data-testid="role-user">{{ r.user }}</td>
              <td data-testid="role-value">{{ r.role }}</td>
            </tr>
          }
          @if (typedDefault(); as name) {
            <tr [attr.data-testid]="'role-row-' + name">
              <td data-testid="role-user">{{ name }}</td>
